/*
 * A363733  Array read by upwards antidiagonals. The family of polynomials
 *          generated by the divisibility matrix (A113704) evaluated over the
 *          nonnegative integers.
 * https://oeis.org/A363733
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 39, u16 n <= 65, u32 n <= 65, u64 n <= 65, u128 n <= 65,
 *            big any n
 * Helpers:   big_pow
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Sequence A363733: array A(n,k) read by upwards antidiagonals.
 * The 2‑D array A(i,j) is defined by
 *   A(0,j) = 1,
 *   A(n,j) = Σ_{d|n, d>0} j^d   (for n ≥ 1).
 * The sequence a(n) lists the entries of A(i,j) in the order
 *   (0,0), (1,0), (0,1), (2,0), (1,1), (0,2), …
 * i.e. by increasing sum i+j and, for a fixed sum, with i decreasing.
 */

#include <math.h>
#include "../utils/big_pow.h"

seq_t a(idx_t n)
{
    /* Determine the antidiagonal (sum) s and the offset within it */
    idx_t s = (idx_t)((sqrtl((long double)8 * n + 1) - 1) / 2);
    /* Correct possible off‑by‑one due to rounding errors */
    while ((s + 1) * (s + 2) / 2 <= n) ++s;
    while (s > 0 && s * (s + 1) / 2 > n) --s;

    idx_t start   = s * (s + 1) / 2;   /* first index of diagonal s */
    idx_t offset  = n - start;        /* 0 ≤ offset ≤ s      */
    idx_t i = s - offset;             /* row index            */
    idx_t j = offset;                 /* column index         */

    /* Base case: row 0 contains only 1s */
    if (i == 0) return (seq_t)1;

    /* Sum j^d over all positive divisors d of i */
    seq_t result = 0;
    idx_t limit = (idx_t)floor(sqrt((long double)i));
    for (idx_t d = 1; d <= limit; ++d) {
        if (i % d == 0) {
            seq_t p = big_pow((seq_t)j, (seq_t)d);
            result += p;
            idx_t other = i / d;
            if (other != d) {
                seq_t p2 = big_pow((seq_t)j, (seq_t)other);
                result += p2;
            }
        }
    }
    return result;
}
